using IndieRun;
using System.IO;
using System.Reflection;
using System.Text.Json;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Markup;
using System.Windows.Media;
using System.Windows.Media.Imaging;
using System.Windows.Threading;
using System.Xml.Linq;
class Program
{
    static void Check(bool ok,string message){if(!ok)throw new Exception(message);}
    static void Set(object o,string name,object? value)=>o.GetType().GetField(name,BindingFlags.NonPublic|BindingFlags.Instance)!.SetValue(o,value);
    static T Get<T>(object o,string name)=>(T)o.GetType().GetField(name,BindingFlags.NonPublic|BindingFlags.Instance)!.GetValue(o)!;
    static object? Call(object o,string name,params object?[] args)=>o.GetType().GetMethod(name,BindingFlags.NonPublic|BindingFlags.Instance|BindingFlags.DeclaredOnly)!.Invoke(o,args);
    static void Wait(Task task){var f=new DispatcherFrame();task.ContinueWith(_=>Application.Current.Dispatcher.BeginInvoke(new Action(()=>f.Continue=false)));Dispatcher.PushFrame(f);task.GetAwaiter().GetResult();}
    static void Close(MainWindow w){Set(w,"closingWithoutSave",true);w.Close();}
    static void Capture(MainWindow w,string file,int width=1150,int height=800)
    {
        var body=(FrameworkElement)w.Content;body.Measure(new Size(width,height));body.Arrange(new Rect(0,0,width,height));body.UpdateLayout();
        var bitmap=new RenderTargetBitmap(width,height,96,96,PixelFormats.Pbgra32);var bg=new DrawingVisual();using(var drawing=bg.RenderOpen())drawing.DrawRectangle((Brush)Application.Current.FindResource("Surface.Window"),null,new Rect(0,0,width,height));bitmap.Render(bg);bitmap.Render(body);var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(bitmap));using var output=File.Create(file);encoder.Save(output);
    }
    static MainWindow Window(string dir,out Package game)
    {
        var input=Path.Combine(dir,"input");var path=Path.Combine(input,"OriginalGame");Directory.CreateDirectory(path);File.WriteAllText(Path.Combine(path,"Game.exe"),"harmless generated fixture, never execute");File.WriteAllText(Path.Combine(path,"save.dat"),"fixture save");
        game=new(){Id=Guid.NewGuid().ToString("N"),IsReal=true,Registered=true,Source=path,DetectedRoot=path,SearchRoot=input,Name="OriginalGame",Folder="OriginalGame",Alias=""};LibraryStore.EnsureIdentity(path,game.Id);var scan=GameScanner.Scan(input);scan.PrepareIndex();var plan=new WorkspaceDocument{SearchRoot=input,SearchLocations=[new(){Path=input}],Destination=Path.Combine(dir,"library"),BackupRoot=Path.Combine(dir,"backups"),Packages=[game],Checkpoints=[WorkspaceReconciler.Capture(game,scan)]};
        var store=new WorkspaceStore(Path.Combine(dir,"data","workspace.json"));store.Save(plan);var w=new MainWindow();new System.Windows.Interop.WindowInteropHelper(w).EnsureHandle();Set(w,"workspaceStore",store);Set(w,"workspaceLock",store.AcquireLock());Call(w,"ApplyWorkspace",plan);Set(w,"snapshot",scan);Set(w,"sessionReady",true);Set(w,"playerRoot",plan.Destination);Set(w,"playerDocument",new PlayerDocument());return w;
    }
    static (BackupEngine Engine,BackupJob Backup,MoveJob Move) Move(string dir,Package game)
    {var engine=new BackupEngine(Path.Combine(dir,"backups"));var backup=Task.Run(()=>engine.CreateAsync(game,[])).GetAwaiter().GetResult();var move=Task.Run(()=>engine.MoveAsync(backup.Id,Path.Combine(dir,"library","RenamedGame"))).GetAwaiter().GetResult();return(engine,backup,move);}
    [STAThread]static int Main(string[] args)
    {
        var root=Path.GetFullPath(args[0]);Directory.CreateDirectory(root);var results=new List<object>();int failed=0;
        void Test(string name,Action<string> action){try{var dir=Path.Combine(root,name);Directory.CreateDirectory(dir);action(dir);results.Add(new{name,passed=true});Console.WriteLine("PASS "+name);}catch(Exception ex){failed++;results.Add(new{name,passed=false,error=ex.ToString()});Console.WriteLine("FAIL "+name+" "+ex.Message);}}
        Test("interrupted-state-is-never-complete",dir=>{var s=new OperationStatus("이동",[new("a","fixture")]);s.Mark("a","Interrupted");s.Finish(false);Check(!s.Heading.EndsWith("완료"),"Interrupted reported complete");});
        Test("pending-state-is-never-complete",dir=>{var s=new OperationStatus("이동",[new("a","fixture")]);s.Finish(false);Check(!s.Heading.EndsWith("완료"),"Unprocessed reported complete");});
        Test("save-pending-is-distinct-from-complete",dir=>{var s=new OperationStatus("이동",[new("a","fixture")]);s.Mark("a","SavePending");s.Finish(false);Check(!s.Heading.EndsWith("완료")&&s.SavePending==1&&s.NeedsAttention,"Unsaved projection reported fully complete");});
        var app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};var styles=XDocument.Load(Path.Combine(AppContext.BaseDirectory,"styles-source.xaml")).Root!.Elements().Single().Elements().Single();app.Resources=(ResourceDictionary)XamlReader.Parse(styles.ToString(),new ParserContext{BaseUri=new Uri(AppContext.BaseDirectory)});SynchronizationContext.SetSynchronizationContext(new DispatcherSynchronizationContext());
        Test("stale-completed-record-cannot-invent-a-location",dir=>{var w=Window(dir,out var p);try{var f=Move(dir,p);Directory.Move(f.Move.Destination,f.Move.Source);Wait((Task)Call(w,"SyncMovedPackagesAsync")!);Check(p.Source==f.Move.Source&&!p.Done,"Historical record pointed UI at nonexistent destination");Check(File.Exists(Path.Combine(p.Source,"Game.exe")),"Live source lost");}finally{Close(w);}});
        Test("both-physical-copies-cannot-be-applied-as-completed",dir=>{var w=Window(dir,out var p);try{var f=Move(dir,p);Directory.CreateDirectory(f.Move.Source);foreach(var file in Directory.GetFiles(f.Move.Destination))File.Copy(file,Path.Combine(f.Move.Source,Path.GetFileName(file)));Call(w,"ApplyMoveToWorkspace",f.Backup,f.Move);Check(p.Source==f.Move.Source&&!p.Done,"Two copies silently treated as a finished move");}finally{Close(w);}});
        Test("source-recreated-before-finalization-is-not-complete",dir=>{var w=Window(dir,out var p);try{var engine=new BackupEngine(Path.Combine(dir,"backups"));var backup=Task.Run(()=>engine.CreateAsync(p,[])).GetAwaiter().GetResult();var target=Path.Combine(dir,"library","Moved");typeof(BackupEngine).GetProperty("Checkpoint",BindingFlags.NonPublic|BindingFlags.Instance)!.SetValue(engine,(Action<string>)(stage=>{if(stage=="move-published"){Directory.CreateDirectory(p.Source);File.WriteAllText(Path.Combine(p.Source,"Game.exe"),"another physical source remains");}}));bool refused=false;try{Task.Run(()=>engine.MoveAsync(backup.Id,target)).GetAwaiter().GetResult();}catch(IOException){refused=true;}Check(refused&&engine.ListMoves(false).Single().Status!="Completed","Engine marked complete while original game path remained");Check(File.Exists(Path.Combine(p.Source,"Game.exe"))&&File.Exists(Path.Combine(target,"Game.exe")),"Unexpected file removal during collision");}finally{Close(w);}});
        Test("cached-games-are-not-hidden-under-collapsed-review",dir=>{var w=Window(dir,out var p);try{p.ReviewState="cached";Set(w,"snapshot",null);Call(w,"RenderCandidates");Check(((StackPanel)w.FindName("CandidateList")).Children.OfType<Grid>().Count()==1,"Saved game disappeared into collapsed review");}finally{Close(w);}});
        Test("renamed-game-stays-visible-under-original-search",dir=>{var w=Window(dir,out var p);try{((TextBox)w.FindName("Search")).Text="OriginalGame";var f=Move(dir,p);Call(w,"ApplyMoveToWorkspace",f.Backup,f.Move);Call(w,"RenderCandidates");Check(((StackPanel)w.FindName("CandidateList")).Children.OfType<Grid>().Count()+((StackPanel)w.FindName("CandidateReviewList")).Children.OfType<Grid>().Count()==1,"Moved item disappeared because the folder name changed");}finally{Close(w);}});
        Test("already-applied-stale-record-is-visible-as-location-issue",dir=>{var w=Window(dir,out var p);try{var f=Move(dir,p);Call(w,"ApplyMoveToWorkspace",f.Backup,f.Move);Directory.Move(f.Move.Destination,f.Move.Source);((TextBox)w.FindName("Search")).Text="OriginalGame";Wait((Task)Call(w,"SyncMovedPackagesAsync")!);Call(w,"RenderCandidates");Check(p.ReviewState=="unverified"&&!p.Done,"Already-applied history bypassed actual location check");Check(((Expander)w.FindName("CandidateReviewSection")).IsExpanded&&((StackPanel)w.FindName("CandidateReviewList")).Children.OfType<Grid>().Count()==1,"Affected game still hidden");}finally{Close(w);}});
        Test("latest-interrupted-record-does-not-replay-older-success",dir=>{var w=Window(dir,out var p);try{var f=Move(dir,p);Directory.Move(f.Move.Destination,f.Move.Source);var pending=JsonSerializer.Deserialize<MoveJob>(JsonSerializer.Serialize(f.Move))!;pending.Id=Guid.NewGuid().ToString("N");pending.Status="Interrupted";pending.Phase="Checking";pending.UpdatedUtc=DateTime.UtcNow.AddMinutes(1);File.WriteAllText(Path.Combine(dir,"backups",f.Backup.Id,"moves",pending.Id+".json"),JsonSerializer.Serialize(pending));Wait((Task)Call(w,"SyncMovedPackagesAsync")!);Check(p.Source==f.Move.Source&&p.ReviewState.Length==0,"Old completed operation replayed over a newer incomplete one");}finally{Close(w);}});
        Test("selective-move-retains-only-excluded-content",dir=>{var w=Window(dir,out var p);try{var omitted=Path.Combine(p.Source,"Extras");Directory.CreateDirectory(omitted);File.WriteAllText(Path.Combine(omitted,"guide.txt"),"left behind deliberately");p.OmittedFolders.Add("Extras");var f=Move(dir,p);Check(f.Move.Status=="Completed"&&Directory.Exists(f.Move.Source)&&File.Exists(Path.Combine(omitted,"guide.txt")),"Excluded content removed");Check(!File.Exists(Path.Combine(f.Move.Source,"Game.exe"))&&File.Exists(Path.Combine(f.Move.Destination,"Game.exe")),"Main executable did not leave source");var evidence=MoveEvidence.Inspect(f.Backup,f.Move);Check(evidence.MatchesRecord&&evidence.RetainedSource,"Correct retained directory treated as a failed move");Call(w,"ApplyMoveToWorkspace",f.Backup,f.Move);Check(p.Done&&p.Source==f.Move.Destination,"Valid selective result not applied");}finally{Close(w);}});
        Test("manual-reconnection-wins-over-old-move-history",dir=>{var w=Window(dir,out var p);try{var f=Move(dir,p);Call(w,"ApplyMoveToWorkspace",f.Backup,f.Move);Directory.Move(f.Move.Destination,f.Move.Source);var current=(WorkspaceDocument)Call(w,"CaptureWorkspace")!;var part=GameScanner.Scan(f.Move.Source);var next=ReconnectPlanner.Prepare(current,p.Id,f.Move.Source,part,new(),new());Call(w,"ApplyWorkspace",next);Wait((Task)Call(w,"SyncMovedPackagesAsync")!);Check(Get<List<Package>>(w,"packages").Single().Source==f.Move.Source&&!Get<List<Package>>(w,"packages").Single().Done,"History undid explicit reconnection");}finally{Close(w);}});
        Test("settings-save-failure-after-real-move-is-not-completed",dir=>{var w=Window(dir,out var p);FileStream? held=null;try{Set(w,"backupEngineFactory",(Func<BackupEngine>)(()=>{var engine=new BackupEngine(Path.Combine(dir,"backups"));typeof(BackupEngine).GetProperty("Checkpoint",BindingFlags.NonPublic|BindingFlags.Instance)!.SetValue(engine,(Action<string>)(phase=>{if(phase=="move-completed")held=new FileStream(Path.Combine(dir,"data","workspace.json"),FileMode.Open,FileAccess.ReadWrite,FileShare.None);}));return engine;}));Wait((Task)Call(w,"ExecuteMoveListAsync",new MoveSelection(new[]{p},Get<List<Package>>(w,"packages")).Items(Path.Combine(dir,"library")),Path.Combine(dir,"library"))!);var state=Get<OperationStatus>(w,"operationStatus");Check(state.Finished&&state.SavePending==1&&state.Done==0&&!state.Heading.EndsWith("완료"),"Metadata failure was reported as completed");Check(!Directory.Exists(Path.Combine(dir,"input","OriginalGame"))&&File.Exists(Path.Combine(dir,"library","OriginalGame","Game.exe")),"Real move not preserved after metadata failure");}finally{held?.Dispose();Close(w);}});
        Test("mismatched-backup-pair-cannot-apply",dir=>{var w=Window(dir,out var p);try{var f=Move(dir,p);var wrong=JsonSerializer.Deserialize<MoveJob>(JsonSerializer.Serialize(f.Move))!;wrong.BackupId=Guid.NewGuid().ToString("N");Check(!MoveEvidence.Inspect(f.Backup,wrong).MatchesRecord,"Unrelated backup accepted");}finally{Close(w);}});
        Test("selective-nested-exclusion-retains-ancestor-directory",dir=>{var w=Window(dir,out var p);try{var keep=Path.Combine(p.Source,"Main","Extras");Directory.CreateDirectory(keep);File.WriteAllText(Path.Combine(keep,"guide.txt"),"keep");File.WriteAllText(Path.Combine(p.Source,"Main","Main.exe"),"fixture executable");p.DetectedRoot=Path.Combine(p.Source,"Main");p.OmittedFolders.Add(Path.Combine("Main","Extras"));var f=Move(dir,p);Check(f.Move.Status=="Completed"&&File.Exists(Path.Combine(keep,"guide.txt"))&&!File.Exists(Path.Combine(f.Move.Source,"Game.exe"))&&!File.Exists(Path.Combine(f.Move.Source,"Main","Main.exe")),"Required excluded ancestors failed finalization");}finally{Close(w);}});
        Test("selective-recreated-main-file-rolls-back-not-completes",dir=>{var w=Window(dir,out var p);try{Directory.CreateDirectory(Path.Combine(p.Source,"Extras"));File.WriteAllText(Path.Combine(p.Source,"Extras","keep.txt"),"keep");p.OmittedFolders.Add("Extras");var engine=new BackupEngine(Path.Combine(dir,"backups"));var backup=Task.Run(()=>engine.CreateAsync(p,[])).GetAwaiter().GetResult();var target=Path.Combine(dir,"library","Moved");bool injected=false;typeof(BackupEngine).GetProperty("Checkpoint",BindingFlags.NonPublic|BindingFlags.Instance)!.SetValue(engine,(Action<string>)(stage=>{if(!injected&&stage=="selective-remove-file"&&!File.Exists(Path.Combine(p.Source,"Game.exe"))&&!File.Exists(Path.Combine(p.Source,"save.dat"))){injected=true;File.Copy(Path.Combine(target,"Game.exe"),Path.Combine(p.Source,"Game.exe"));}}));bool refused=false;try{Task.Run(()=>engine.MoveAsync(backup.Id,target)).GetAwaiter().GetResult();}catch(IOException){refused=true;}Check(injected&&refused&&engine.ListMoves(false).Single().Status=="RolledBack","Selective move ignored recreated source file");Check(File.Exists(Path.Combine(p.Source,"Game.exe"))&&File.Exists(Path.Combine(p.Source,"Extras","keep.txt"))&&!Directory.Exists(target),"Selective rollback lost source content");}finally{Close(w);}});
        Test("main-execution-scope-cannot-be-excluded-from-plan",dir=>{var w=Window(dir,out var p);try{var main=Path.Combine(p.Source,"Main");Directory.CreateDirectory(main);p.DetectedRoot=main;p.OmittedFolders.Add("Main");Check(CompositionPlan.AnchorProblem(p)!=null,"Excluded declared main scope accepted");bool refused=false;try{CompositionPlan.Preflight(new BackupEngine(Path.Combine(dir,"backups")),[p],Path.Combine(dir,"library"));}catch(IOException){refused=true;}Check(refused&&Directory.Exists(p.Source),"Invalid main scope altered source");}finally{Close(w);}});
        Test("default-executable-cannot-be-excluded-from-plan",dir=>{var w=Window(dir,out var p);try{p.OmittedFolders.Add("Main");Check(CompositionPlan.AnchorProblem(p,new GamePlay{Id=p.Id,Executable=Path.Combine("Main","Game.exe")})!=null,"Excluded default executable accepted");}finally{Close(w);}});
        Test("ui-observes-real-files-instead-of-copying-backup-manifest",dir=>{var w=Window(dir,out var p);try{var target=Path.Combine(dir,"library","OriginalGame");Set(w,"backupEngineFactory",(Func<BackupEngine>)(()=>{var engine=new BackupEngine(Path.Combine(dir,"backups"));typeof(BackupEngine).GetProperty("Checkpoint",BindingFlags.NonPublic|BindingFlags.Instance)!.SetValue(engine,(Action<string>)(phase=>{if(phase=="move-completed")File.WriteAllText(Path.Combine(target,"observed-after-move.txt"),"only the real filesystem has this file");}));return engine;}));Wait((Task)Call(w,"ExecuteMoveListAsync",new MoveSelection(new[]{p},Get<List<Package>>(w,"packages")).Items(Path.Combine(dir,"library")),Path.Combine(dir,"library"))!);var snapshot=Get<ScanSnapshot>(w,"snapshot");Check(snapshot.Files.Any(f=>f.Path==Path.Combine(target,"observed-after-move.txt")),"UI fabricated the old manifest instead of observing the result");Check(!snapshot.Files.Any(f=>f.Path==Path.Combine(dir,"input","OriginalGame","Game.exe")),"UI still displays vanished source files");Check(Get<List<FolderCheckpoint>>(w,"checkpoints").Single().Files.Any(f=>f.RelativePath=="observed-after-move.txt"),"Current baseline was invented from an old backup");}finally{Close(w);}});
        Test("location-issue-wpf-layout",dir=>{var w=Window(dir,out var p);try{var f=Move(dir,p);Call(w,"ApplyMoveToWorkspace",f.Backup,f.Move);Directory.Move(f.Move.Destination,f.Move.Source);((TextBox)w.FindName("Search")).Text="OriginalGame";Wait((Task)Call(w,"SyncMovedPackagesAsync")!);Call(w,"SetPage","organize");Call(w,"Render");Check(((Button)w.FindName("ReconnectButton")).Content as string=="이동 위치 확인","Wrong repair action");Capture(w,Path.Combine(dir,"location-issue.png"));Call(w,"SetPage","jobs");Call(w,"RenderBackupJobs");Wait((Task)Call(w,"RefreshHistoryAsync")!);Capture(w,Path.Combine(dir,"location-jobs.png"));}finally{Close(w);}});
        File.WriteAllText(args[1],JsonSerializer.Serialize(new{total=results.Count,passed=results.Count-failed,failed,results},new JsonSerializerOptions{WriteIndented=true}));return failed==0?0:1;
    }
}
